def bundle(code):
    out = dict(EN)
    out.update(STRINGS.get(code, {}))
    return out

def coverage(code):
    """Share of English UI keys that have a real translation (English itself is 100)."""
    if code == "en":
        return 100
    have = STRINGS.get(code, {})
    return int(100 * sum(1 for k in EN if k in have) / len(EN))

